import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, CanvasTexture, Color, LinearFilter, SRGBColorSpace } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep, float, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = 'hub-pricing-card-label-2';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const surfaceCol = new THREE.Color(colors.surface ?? '#0b0b10');
  const ink = new THREE.Color(colors.ink ?? '#16161d');
  const paper = new THREE.Color(colors.paper ?? '#e8ecf2');
  const accent = new THREE.Color(colors.accent ?? '#ff2a38');

  // Backdrop plane carrying engineered gradient — fill its local frame
  const aspectRatio = 512 / 320;
  const planeW = 0.85;
  const planeH = planeW / aspectRatio;

  // Engineered gradient via TSL — vertical signal-red glow anchor at top, fade into ink/surface
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.transparent = true;

  const baseGrad = mix(
    vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b),
    vec3(ink.r, ink.g, ink.b),
    smoothstep(float(0.0), float(0.55), uv().y)
  );
  const accentGlow = mix(
    vec3(accent.r, accent.g, accent.b),
    vec3(0.0, 0.0, 0.0),
    smoothstep(float(0.0), float(0.38), uv().y)
  );
  const accentBlend = accentGlow.mul(float(0.22));
  bgMat.colorNode = baseGrad.add(accentBlend);

  const bgGeo = new THREE.PlaneGeometry(planeW, planeH);
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -0.001);
  group.add(bgMesh);

  // Subtle grain via TSL (fractal hash approximation)
  const grainTSL = fract(uv().x.mul(float(137.0)).add(uv().y.mul(float(347.0)))).sub(float(0.5));
  bgMat.colorNode = baseGrad.add(accentBlend).add(grainTSL.mul(float(0.012)));

  // Image plate — inset, subtle, as engraved accent
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      const imgMat = new MeshBasicNodeMaterial({ transparent: true });
      imgMat.opacityNode = float(0.42);
      imgMat.map = tex;
      imgMat.colorNode = texture(tex, uv());
      imgMat.colorNode = mix(texture(tex), vec3(paper.r, paper.g, paper.b), float(0.34)).mul(float(0.85));
      imgMat.opacityNode = float(0.42);
      imgMat.needsUpdate = true;
      const imgGeo = new THREE.PlaneGeometry(planeW * 0.78, planeH * 0.78);
      const imgMesh = new THREE.Mesh(imgGeo, imgMat);
      imgMesh.position.set(0, 0, 0.024);
      group.add(imgMesh);
    });
  }

  // Left accent rule — engineered bar
  const ruleMat = new THREE.MeshBasicNodeMaterial();
  ruleMat.colorNode = vec3(accent.r, accent.g, accent.b);
  const ruleGeo = new THREE.PlaneGeometry(0.018, planeH * 0.62);
  const ruleMesh = new THREE.Mesh(ruleGeo, ruleMat);
  ruleMesh.position.set(-planeW * 0.5 + 0.05, 0, 0.02);
  group.add(ruleMesh);

  // Top hairline
  const hairMat = new THREE.MeshBasicNodeMaterial();
  hairMat.colorNode = vec3(paper.r, paper.g, paper.b).mul(float(0.22));
  const hairGeo = new THREE.PlaneGeometry(planeW * 0.84, 0.006);
  const hairMesh = new THREE.Mesh(hairGeo, hairMat);
  hairMesh.position.set(0, planeH * 0.4, 0.02);
  group.add(hairMesh);

  // Text — MSDF via ctx.fontAtlas
  const headline = items.find((it) => it.role === 'headline') ?? items[0];
  if (headline && ctx.fontAtlas) {
    const label = ctx.fontAtlas.createText(String(headline.text), {
      fontSize: Math.round((headline.typography?.fontSize ?? 39) * 0.7),
      color: paper.getStyle(),
      align: 'left',
      letterSpacingPx: 0.6,
    });
    label.position.set(-planeW * 0.5 + 0.078, 0, 0.04);
    group.add(label);
  }

  // Mono caption — "PRICING-TIER / 03"
  if (ctx.fontAtlas) {
    const caption = ctx.fontAtlas.createText('TIER 03', {
      fontSize: 18,
      color: accent.getStyle(),
      align: 'left',
      letterSpacingPx: 2.4,
    });
    caption.position.set(-planeW * 0.5 + 0.078, planeH * 0.32, 0.04);
    group.add(caption);
  }

  // Entrance — fade-up (no primitive requested)
  const tl = gsap.timeline();
  group.position.set(0, 0.2, 0);
  group.scale.set(0.98, 0.98, 0.98);
  group.visible = true;
  tl.to(group.position, { y: 0, duration: 0.5, ease: 'power2.out' }, 0)
    .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0)
    .fromTo(group, { renderOrder: 0 }, { duration: 0.01 }, 0);

  // We track display opacity via a container — wrap fade on children materials is complex; leave visible.

  // Static composition positioning — adapter applies scenePosition, so group is centered.

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    bgGeo.dispose();
    bgMat.dispose();
    ruleGeo.dispose();
    ruleMat.dispose();
    hairGeo.dispose();
    hairMat.dispose();
    group.traverse((o) => {
      if (o.geometry && o.geometry !== bgGeo) o.geometry?.dispose?.();
      if (o.material && o.material !== bgMat && o.material !== ruleMat && o.material !== hairMat) {
        o.material?.dispose?.();
      }
    });
  };

  return group;
}
